// Extrai dados da mensagem do WhatsApp
const body = $input.first().json.body;
const message = body.data?.message;
const key = body.data?.key;

const telefone = key?.remoteJid?.replace('@s.whatsapp.net', '') || '';
const texto = message?.conversation || 
              message?.extendedTextMessage?.text || 
              '';
const nomeRemetente = body.data?.pushName || 'Paciente';
const messageId = key?.id || '';

return [{
  json: {
    telefone,
    texto,
    nomeRemetente,
    messageId,
    timestamp: new Date().toISOString()
  }
}];

// Gera lista de horários disponíveis com base na agenda
// Horário de atendimento: Segunda a Sexta 8h-18h, Sábado 8h-12h
const ocupados = $input.first().json.busy || [];
const ocupadosSet = new Set(ocupados.map(b => b.start));

const horarios = [];
const agora = new Date();

for (let d = 1; d <= 14; d++) {
  const data = new Date(agora);
  data.setDate(data.getDate() + d);
  const diaSemana = data.getDay();

  // Pula domingo (0)
  if (diaSemana === 0) continue;

  // Sábado só até 12h
  const horaFim = diaSemana === 6 ? 12 : 18;

  for (let h = 8; h < horaFim; h++) {
    const slot = new Date(data);
    slot.setHours(h, 0, 0, 0);
    const slotISO = slot.toISOString();

    if (!ocupadosSet.has(slotISO)) {
      horarios.push({
        iso: slotISO,
        display: slot.toLocaleDateString('pt-BR', { 
          weekday: 'long', day: '2-digit', month: '2-digit' 
        }) + ' às ' + h + ':00'
      });
    }
  }
}

// Retorna os próximos 6 slots disponíveis
return [{ json: { horarios: horarios.slice(0, 6) } }];

