// Extrai a resposta do Claude e detecta se houve confirmação de horário
const claudeResponse = $input.first().json;
const textoResposta = claudeResponse.content[0].text;

// Tenta detectar se o paciente escolheu um horário (análise simples)
const mensagemOriginal = $('Extrai Dados da Mensagem').item.json.texto.toLowerCase();
const horarios = $('Processa Horários Disponíveis').item.json.horarios;

let horarioEscolhido = null;
const numEscolhido = parseInt(mensagemOriginal.match(/\b([1-6])\b/)?.[1]);
if (numEscolhido && numEscolhido >= 1 && numEscolhido <= horarios.length) {
  horarioEscolhido = horarios[numEscolhido - 1];
}

return [{
  json: {
    textoResposta,
    horarioEscolhido,
    deveAgendar: horarioEscolhido !== null
  }
}];
